ATTACH ':memory:' AS db (
  TYPE adbc, driver 'sqlite'
);
SELECT * FROM adbc_scan(
  'db', 'SELECT ? AS id',
  params := row(42),
  columns := {'id': 'BIGINT'}
);

ATTACH 'grpc://localhost:8815' AS remote
  (TYPE airport);
SHOW TABLES FROM remote.public;
SELECT user_id, count(*) AS n
FROM remote.public.activity
GROUP BY user_id
ORDER BY n DESC
LIMIT 10;
DETACH remote;

CREATE TEMP TABLE response AS
SELECT http_get('https://example.com/') AS r;
SELECT (r->>'status')::INTEGER AS status,
       r->>'reason' AS reason,
       r->>'body' AS body
FROM response;

SELECT httpserve_start(
  'localhost', 9999, 'replace-this-key'
);

SET VARIABLE feed = 'ws://localhost:8765/';
CALL radio_subscribe(getvariable('feed'));
CALL radio_listen(true, INTERVAL '5 seconds');
SELECT receive_time, channel,
       decode(message) AS text
FROM radio_received_messages()
WHERE subscription_url = getvariable('feed')
ORDER BY receive_time DESC
LIMIT 20;

CREATE TABLE users_snapshot AS
SELECT key, field, value
FROM redis_hscan_over_scan(
  'user:*', '*', 100, 'quickref_redis'
);
SELECT key, count(*) AS fields
FROM users_snapshot
GROUP BY key;

SELECT sum(n) AS total
FROM read_csv(
  'printf "n\n1\n2\n3\n" |',
  header = true
);
-- 6

ATTACH 'analytics' AS app (
  TYPE vgi,
  LOCATION 'https://worker.example.com/vgi/'
);
SHOW TABLES FROM app.main;
SELECT * FROM app.main.events
LIMIT 10;
DETACH app;

SELECT octet_length(crypto_random_bytes(32));

SELECT to_hex(crypto_hash_agg(
  'sha2-256', s ORDER BY s
)) AS digest
FROM (VALUES ('A'), ('B')) AS t(s);

SELECT typeof(xxh3_64('hello')) AS small,
       typeof(xxh3_128('hello')) AS large;
-- UBIGINT, UHUGEINT

SELECT inflector_to_table_case('UserAccount');
-- user_accounts
SELECT inflector_to_plural('person');
-- people
SELECT inflector_to_singular('people');
-- person

SELECT result::INTEGER AS value
FROM quickjs(
  'parsed_arg0.map(x => x * arg1)',
  '[1,2,3]', 3
);
-- 3, 6, 9

SELECT salary, evalexpr_rhai(
  'context.salary >= 100000',
  {'salary': salary}
).ok::BOOLEAN AS eligible
FROM (VALUES (80000), (120000)) t(salary);
-- false, true

SELECT * FROM events
ORDER BY id DESC LIMIT 2;

SET VARIABLE cursor = (
  SELECT id FROM events
  ORDER BY id DESC LIMIT 1 OFFSET 1
);
SELECT * FROM events
WHERE id < getvariable('cursor')
ORDER BY id DESC LIMIT 2;

WITH draws AS MATERIALIZED (
  SELECT
    dist_uniform_real_sample(-1, 1) AS x,
    dist_uniform_real_sample(-1, 1) AS y
  FROM range(100000)
)
SELECT 4.0 * AVG(
  (x*x + y*y <= 1)::INTEGER
) AS pi_estimate
FROM draws;

CREATE TABLE plots (
  geom GEOSILO('EPSG:3857')
    USING COMPRESSION zstd
);
INSERT INTO plots VALUES (
  'POLYGON((0 0,10 0,10 10,0 10,0 0))'
    ::GEOMETRY
);

WITH rules AS (
  SELECT marisa_trie(s) AS trie
  FROM (VALUES ('U'), ('US'), ('USA')) t(s)
)
SELECT marisa_common_prefix(trie, 'USA', 10)
FROM rules;

CREATE TEMP TABLE scheduled AS
SELECT cron(
  'SELECT 42', '0 */5 * * * *'
) AS job_id;

SET events_session_name = 'analytics';
SET events_types = [
  'query_begin', 'query_end'
];
SET events_async = TRUE;
SET events_destination =
  '/usr/local/bin/query-events';
SELECT sum(i) FROM range(1000) t(i);

